  String? jti;
  String? mobile;
  String? password;
  String? redirect_uri;
  String? refresh_token;
  String? scope;
  int? user_id;
  String? username;

  AuthenticationServiceV1LoginRequest({
    this.client_id,
    this.client_secret,
    this.client_type,
    this.code,
    this.device_id,
    this.email,
    this.grant_type,
    this.jti,
    this.mobile,
